package ru.meguboom.mobile;
import org.junit.Test;import org.json.*;import java.util.*;import java.io.*;import static org.junit.Assert.*;
public class ProgressSyncTest {
 static final String DEVICE="11111111-1111-4111-8111-111111111111";
 static JSONObject entries()throws Exception{return new JSONObject().put("file",new JSONObject().put("positionMs",100).put("durationMs",1000).put("completed",false).put("updatedAt",200).put("deviceId",DEVICE));}
 @Test public void createsOnlyOwnAppDataFileAndDoesNotUploadUnchanged()throws Exception {List<String> calls=new ArrayList<>();final String[] stored={""};ProgressSync.Transport api=(method,url,body,type)->{calls.add(method+" "+url);if(url.contains("spaces=appDataFolder"))return stored[0].isEmpty()?"{\"files\":[]}":"{\"files\":[{\"id\":\"ownfile\",\"name\":\"meguboom-progress-v1-"+DEVICE+".json\"}]}";if(method.equals("POST")){assertTrue(body.contains("\"parents\":[\"appDataFolder\"]"));stored[0]=ProgressRecords.document(DEVICE,entries()).toString();return "{\"id\":\"ownfile\"}";}if(url.contains("alt=media"))return stored[0];throw new IOException("Unexpected request: "+url);};ProgressSync.exchange(DEVICE,entries(),api);ProgressSync.exchange(DEVICE,entries(),api);assertEquals(1,calls.stream().filter(s->s.startsWith("POST ")).count());assertEquals(0,calls.stream().filter(s->s.startsWith("PATCH ")).count());}
 @Test public void rejectsRepeatedPageAndSkipsMalformedOtherDevice()throws Exception {assertThrows(IOException.class,()->ProgressSync.exchange(DEVICE,entries(),(m,u,b,t)->"{\"files\":[],\"nextPageToken\":\"repeat\"}"));ProgressSync.Result r=ProgressSync.exchange(DEVICE,new JSONObject(),(m,u,b,t)->u.contains("spaces=")?"{\"files\":[{\"id\":\"broken\",\"name\":\"meguboom-progress-v1-other.json\"}]}":"not json");assertEquals(0,r.merged.length());assertEquals(1,r.rejected);}
}
